Command commandShardSqlScript = new Command("sql-script", "Runs SQL script for all shards in the Shard Map Manager. 

Examples:
  .\ElasticShardSqlUtil.exe shard sql-script --file script.sql")              {                  new Option<string>(new []{"--file", "-f"}, "The SQL script to execute.")                  {                      IsRequired = true,                  },              };

